using System.Collections.Generic;
using UnityEngine;

namespace Starline.Client
{
    /// <summary>
    /// Unit models in Resources/StarlineModels/&lt;unit id&gt;.fbx. Models generated by tools/models/build_models.py
    /// share Palette.png; models imported with tools/models/import_model.py (AI-generated or hand-made) bring
    /// their own &lt;model key&gt;_tex.png. Every model has two material slots, "Hull" (that texture) and
    /// "Glow" (emissive parts whose colour the client sets per side and mana network state).
    /// Cartoon characters are rigged and carry their clips (idle, walk, attack, hit, death; see
    /// <see cref="UnitAnimator"/>). They have no base: battle shows them standing on the board, and
    /// showcase screens (roster, star-up, codex) put them on base_s&lt;star&gt; / base_large_s&lt;star&gt;
    /// with <see cref="InstantiateShowcase"/>.
    /// </summary>
    public static class ModelLibrary
    {
        public const string Folder = "StarlineModels";

        private static readonly Dictionary<string, GameObject> Prefabs = new Dictionary<string, GameObject>();
        private static readonly Dictionary<string, Texture2D> Textures = new Dictionary<string, Texture2D>();
        private static readonly Dictionary<string, AnimationClip[]> ClipSets = new Dictionary<string, AnimationClip[]>();

        /// <summary>Height of the top of the showcase base; the character stands on it.</summary>
        public const float BaseTop = 0.08f;
        private static Texture2D _palette;
        private static Shader _lit;

        /// <summary>
        /// The model to use for a unit at a star level. Cartoon characters export one costume per star as
        /// &lt;unit id&gt;_s2 … &lt;unit id&gt;_s5 (each dressier than the last); a star uses the highest tier at or
        /// below it, falling back to the plain ★1 model.
        /// </summary>
        public static string ModelKey(string unitId, int star)
        {
            for (int s = star; s >= 2; s--)
            {
                string key = unitId + "_s" + s;
                if (Prefab(key) != null)
                {
                    return key;
                }
            }
            return unitId;
        }

        /// <summary>Instantiates a model by key (see ModelKey), or returns null when none has been generated.</summary>
        public static GameObject Instantiate(string modelKey, Transform parent)
        {
            GameObject prefab = Prefab(modelKey);
            if (prefab == null)
            {
                return null;
            }
            GameObject model = Object.Instantiate(prefab, parent, false);
            model.name = "Model";
            return model;
        }

        /// <summary>The model's animation clips (empty for static models).</summary>
        public static AnimationClip[] Clips(string modelKey)
        {
            if (!ClipSets.TryGetValue(modelKey, out AnimationClip[] clips))
            {
                var list = new List<AnimationClip>();
                foreach (AnimationClip clip in Resources.LoadAll<AnimationClip>(Folder + "/" + modelKey))
                {
                    if (!clip.name.StartsWith("__preview__"))
                    {
                        list.Add(clip);
                    }
                }
                clips = list.ToArray();
                ClipSets[modelKey] = clips;
            }
            return clips;
        }

        /// <summary>
        /// A character for showcase screens (roster, star-up, codex): the star's costume standing on the
        /// star's base (2×2 characters on the large base), idling. Battle uses the model without a base.
        /// Materials are left to the caller (see <see cref="AssignMaterials"/>); returns null without a model.
        /// </summary>
        public static GameObject InstantiateShowcase(string unitId, int star, int size, Transform parent)
        {
            string modelKey = ModelKey(unitId, star);
            if (Prefab(modelKey) == null)
            {
                return null;
            }
            var root = new GameObject("Showcase " + modelKey);
            root.transform.SetParent(parent, false);
            GameObject stand = Instantiate((size >= 2 ? "base_large_s" : "base_s") + Mathf.Clamp(star, 1, 5), root.transform);
            if (stand != null)
            {
                stand.name = "Base";
            }
            GameObject model = Instantiate(modelKey, root.transform);
            if (stand != null)
            {
                model.transform.localPosition = Vector3.up * BaseTop;
            }
            UnitAnimator.Attach(model, Clips(modelKey));
            return root;
        }

        private static GameObject Prefab(string modelKey)
        {
            if (!Prefabs.TryGetValue(modelKey, out GameObject prefab))
            {
                prefab = Resources.Load<GameObject>(Folder + "/" + modelKey);
                Prefabs[modelKey] = prefab;
            }
            return prefab;
        }

        /// <summary>Gives the model its own hull and glow materials (one pair per unit, so glow can change per unit).</summary>
        public static void AssignMaterials(GameObject model, Material hull, Material glow)
        {
            foreach (Renderer r in model.GetComponentsInChildren<Renderer>())
            {
                Material[] slots = r.sharedMaterials;
                for (int i = 0; i < slots.Length; i++)
                {
                    bool isGlow = slots[i] != null ? slots[i].name.StartsWith("Glow") : i == 1;
                    slots[i] = isGlow ? glow : hull;
                }
                r.sharedMaterials = slots;
            }
        }

        public static Material CreateHullMaterial(string modelKey)
        {
            var material = new Material(LitShader()) { name = "Hull" };
            material.mainTexture = OwnTexture(modelKey) ?? Palette();
            material.color = Color.white;
            material.SetFloat("_Smoothness", 0.35f);
            material.SetFloat("_Glossiness", 0.35f);
            material.EnableKeyword("_EMISSION");
            material.SetColor("_EmissionColor", Color.black);
            return material;
        }

        public static Material CreateGlowMaterial()
        {
            var material = new Material(LitShader()) { name = "Glow" };
            material.color = Color.black;
            material.EnableKeyword("_EMISSION");
            return material;
        }

        /// <summary>The unit's own painted texture (imported models), or null for palette-coloured models.</summary>
        private static Texture2D OwnTexture(string modelKey)
        {
            if (!Textures.TryGetValue(modelKey, out Texture2D texture))
            {
                texture = Resources.Load<Texture2D>(Folder + "/" + modelKey + "_tex");
                Textures[modelKey] = texture;
            }
            return texture;
        }

        private static Texture2D Palette()
        {
            if (_palette == null)
            {
                _palette = Resources.Load<Texture2D>(Folder + "/Palette");
                if (_palette != null)
                {
                    _palette.filterMode = FilterMode.Point; // flat colour blocks, no blending between cells
                }
            }
            return _palette;
        }

        private static Shader LitShader()
        {
            if (_lit == null)
            {
                // The default material of a primitive uses the active pipeline's lit shader
                // (URP Lit, or Standard without URP) and is always included in builds.
                GameObject probe = GameObject.CreatePrimitive(PrimitiveType.Cube);
                _lit = probe.GetComponent<Renderer>().sharedMaterial.shader;
                ViewUtil.DestroySafe(probe);
            }
            return _lit;
        }
    }
}
